"""A self-contained, source-bound circuit explorer with no network dependency."""

from __future__ import annotations

import base64
import hashlib
import html
import json

CSS = r'''
:root{color-scheme:light;--ink:#193446;--muted:#536a79;--paper:#fff;--desk:#e8eff3;--line:#bfd0da;--blue:#13667d;--copper:#ad572e;--green:#25664c;--amber:#925009}
*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--desk);font:15px/1.5 "Segoe UI",Arial,sans-serif}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(30px,4.5vw,58px);letter-spacing:-.035em;line-height:1.08;margin-bottom:10px}h2{font-size:24px;margin-bottom:6px}h3{font-size:16px;margin-bottom:8px}button,input,select{font:inherit;color:inherit}button{cursor:pointer}button,a,input,select,summary{outline-offset:4px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #147a9c}a{color:var(--blue)}button,input,select{border:1px solid #a8bcc9;border-radius:5px;background:white;padding:8px 12px}button:hover{background:#edf5f8}button[aria-pressed=true]{background:var(--blue);border-color:var(--blue);color:white}button:disabled{cursor:default;opacity:.5}.shell{max-width:1800px;margin:auto;padding:28px clamp(14px,3vw,44px) 42px}.mast{display:flex;justify-content:space-between;gap:30px;align-items:end}.brand{color:var(--blue);font-weight:700;margin-bottom:12px}.lead{max-width:67ch;color:var(--muted);font-size:17px;margin-bottom:22px}.notice{max-width:42ch;font-size:13px;color:var(--muted);padding-left:14px;border-left:3px solid var(--copper)}nav{display:flex;gap:8px;flex-wrap:wrap;margin:6px 0 24px}nav button{padding:11px 17px;font-weight:600}.board-head{display:flex;justify-content:space-between;gap:20px;align-items:baseline;margin-bottom:14px}.board-head p{color:var(--muted);margin-bottom:0}.result{white-space:nowrap;color:var(--green);font-size:13px}.workspace{display:grid;grid-template-columns:260px minmax(0,1fr) 290px;min-height:620px;border:1px solid var(--line);border-radius:8px;background:var(--paper);overflow:hidden}.inventory{border-right:1px solid var(--line);display:flex;flex-direction:column;min-width:0}.tools{padding:18px 16px;border-bottom:1px solid var(--line)}.tools label{display:block;color:var(--muted);font-size:13px;margin-bottom:5px}.tools input{width:100%;min-width:0}.parts{max-height:570px;overflow:auto;padding:6px}.part{display:block;text-align:left;width:100%;border:0;border-radius:4px;padding:9px 11px;background:transparent}.part strong{display:inline-block;width:40px}.part span{font-size:13px}.part small{display:block;color:var(--muted);font-size:11px;margin-left:40px;overflow-wrap:anywhere}.part[aria-pressed=true] small{color:#d7f3fa}.count{font-size:12px;color:var(--muted);margin:8px 0 0}.viewer{min-width:0;display:flex;flex-direction:column;background:#f3f7f9}.viewbar{display:flex;gap:6px;flex-wrap:wrap;align-items:center;padding:12px 14px;border-bottom:1px solid var(--line);background:white}.viewbar button{font-size:13px;padding:6px 9px}.viewbar select{margin-left:auto;max-width:210px;font-size:13px}.stage{position:relative;display:flex;align-items:center;justify-content:center;min-height:440px;flex:1;overflow:auto;background:linear-gradient(0deg,#eff5f8 1px,transparent 1px),linear-gradient(90deg,#eff5f8 1px,transparent 1px),#e1eaf0;background-size:24px 24px;padding:18px}.stage>img{display:block;max-width:100%;max-height:560px;object-fit:contain}.stage>img.model{filter:drop-shadow(0 16px 12px #22384b27)}.stage svg{width:100%;max-height:560px;min-height:360px;display:block;touch-action:manipulation}.stage svg .route{opacity:.55}.stage svg .dim{opacity:.09}.stage svg .hit{stroke:#f2b537!important;opacity:1!important}.stage svg .pad{cursor:pointer;stroke:#e6d7a2;stroke-width:.08}.stage svg .pad:hover{stroke:#f2b537;stroke-width:.35}.stage svg .mechanical{fill:#d4dee5;stroke:#607b8c;stroke-width:.1}.stage svg .marker{fill:none;stroke:#1673a0;stroke-width:.22;stroke-dasharray:.55 .35;pointer-events:none}.stage svg text{font-family:"Segoe UI",Arial,sans-serif;fill:#173346;paint-order:stroke;stroke:#f4f8fb;stroke-width:.4px;stroke-linejoin:round;font-size:1.2px;pointer-events:none}.caption{min-height:65px;border-top:1px solid var(--line);padding:12px 16px;color:var(--muted);font-size:12px;background:white}.detail{padding:18px 18px 22px;border-left:1px solid var(--line);min-width:0}.detail .mpn{font-size:17px;font-weight:650;overflow-wrap:anywhere;margin-bottom:8px}.detail .field{font-size:12px;color:var(--muted);overflow-wrap:anywhere;margin-bottom:16px}.detail table{width:100%;border-collapse:collapse;font-size:13px}.detail th{text-align:left;color:var(--muted);font-size:12px;font-weight:500}.detail td,.detail th{padding:6px 3px;border-bottom:1px solid #e1e9ee}.detail td button{font-size:12px;padding:3px 6px;border-color:transparent;background:#edf3f6;overflow-wrap:anywhere;text-align:left}.detail td button.selected{background:var(--blue);color:white}.detail .sources{padding-left:18px;font-size:12px}.detail li{margin-bottom:9px}.detail li small{display:block;color:var(--muted)}.bottom{display:grid;grid-template-columns:1.3fr 1fr;gap:22px;margin-top:22px}.boundaries,.ledger{background:white;border:1px solid var(--line);border-radius:7px;padding:20px 22px}.boundaries p,.ledger p{font-size:13px;color:var(--muted);max-width:85ch}.boundary-list{padding-left:20px;font-size:13px}.boundary-list li{margin-bottom:8px}code{font-family:Consolas,monospace;font-size:.85em;overflow-wrap:anywhere}.fingerprint{display:block;margin-top:6px;color:var(--ink)}details summary{cursor:pointer;font-weight:600}.ledger dl{font-size:12px}.ledger dt{margin-top:12px;color:var(--muted)}.ledger dd{margin:4px 0 0}.download{display:inline-block;font-size:13px;padding:8px 0}.empty{padding:15px;color:var(--muted);font-size:13px}[hidden]{display:none!important}.footer{color:var(--muted);font-size:12px;margin-top:22px}.skip{position:absolute;left:-9999px}.skip:focus{left:15px;top:12px;background:white;padding:10px;z-index:4}.js-only{display:none}.enhanced .js-only{display:flex}noscript{display:block;padding:20px;border:1px solid var(--line);background:white}noscript img{max-width:100%}
@media(max-width:1250px){.workspace{grid-template-columns:220px minmax(0,1fr)}.detail{grid-column:1/-1;border-left:0;border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 1.2fr 1fr;gap:22px}.detail h3{grid-column:1/-1}.stage{min-height:420px}.parts{max-height:500px}}
@media(max-width:750px){.shell{padding-top:20px}.mast{display:block}.notice{max-width:none;margin-bottom:20px}.workspace{grid-template-columns:1fr}.inventory{border-right:0;border-bottom:1px solid var(--line)}.parts{max-height:165px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.tools{padding:12px}.part{padding:8px}.part strong{width:33px}.part small{margin-left:33px}.detail{display:block}.detail table{margin-bottom:20px}.stage{min-height:310px;padding:10px}.stage svg{min-height:290px}.stage>img{max-height:450px}.viewbar select{margin-left:0;width:100%;max-width:none}.board-head{display:block}.result{display:block;margin-top:8px}.bottom{grid-template-columns:1fr}.boundaries,.ledger{padding:17px}nav{gap:6px}nav button{padding:9px 12px;font-size:13px}}
@media(prefers-reduced-motion:no-preference){button{transition:background .13s ease}}
'''

JS = r'''
const data=JSON.parse(document.getElementById('explorer-data').textContent);
const $=id=>document.getElementById(id), ns='http://www.w3.org/2000/svg';
let board=data.boards[0], selected=board.geometry.components.find(p=>p.reference==='U1')||board.geometry.components[0], view='model', net='';
const titles={model:'Native 3D render',map:'Connectivity map',schematic:'Native schematic',top:'Native top copper',bottom:'Native bottom copper'};
function el(tag,text,parent,attrs={}){const e=document.createElement(tag);if(text!==null)e.textContent=text;for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(parent)parent.append(e);return e;}
function svg(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e;}
function match(p,q){return [p.reference,p.value,p.mpn,p.footprint,...p.pads.flatMap(x=>[x.number,x.net])].join(' ').toLowerCase().includes(q);}
function parts(){const q=$('search').value.toLowerCase().trim(), list=$('parts');list.replaceChildren();let n=0;for(const p of board.geometry.components){if(!match(p,q))continue;n++;const b=el('button',null,list,{'class':'part','aria-pressed':String(p===selected)});el('strong',p.reference,b);el('span',p.value,b);el('small',p.mpn||'Fabricated mechanical feature',b);b.addEventListener('click',()=>{selected=p;parts();detail();stage();});}if(!n)el('p','No components match. Try a reference, MPN, pin or net.',list,{'class':'empty'});$('part-count').textContent=`${n} of ${board.geometry.components.length} physical footprints`;}
function chooseNet(value){net=value;$('net').value=value;if(value)view='map';buttons();detail();stage();}
function detail(){const host=$('detail');host.replaceChildren();el('h3',`${selected.reference} / ${selected.value}`,host);const identity=el('div',null,host);el('p',selected.mpn||'Fabricated mechanical feature',identity,{'class':'mpn'});el('p',selected.footprint,identity,{'class':'field'});const position=selected.position.map(n=>n.toFixed(3)).join(', ');el('p',`Native footprint origin: ${position} mm. Positions are inspection aids, not a mechanical drawing.`,identity,{'class':'field'});
 const pinbox=el('div',null,host),t=el('table',null,pinbox),head=el('tr',null,el('thead',null,t));el('th','Pin / pad',head);el('th','Saved net',head);const body=el('tbody',null,t), seen=new Set();for(const pad of selected.pads){const key=pad.number+'\0'+pad.net;if(seen.has(key))continue;seen.add(key);const row=el('tr',null,body);el('td',pad.number||'Hole',row);const cell=el('td',null,row);if(pad.net){const b=el('button',pad.net,cell,{'class':pad.net===net?'selected':''});b.addEventListener('click',()=>chooseNet(pad.net));}else el('span','No net',cell);}
 const sources=el('div',null,host);el('h3','Archived source evidence',sources);const list=el('ul',null,sources,{'class':'sources'});for(const source of selected.sources){const li=el('li',null,list);if(source.url){el('a',source.title,li,{href:source.url,target:'_blank',rel:'noopener noreferrer'});}else el('span',source.title,li);el('small',[source.manufacturer,source.revision].filter(Boolean).join(' / '),li);el('small',`Archived ${source.retrieved_on}`,li);}if(!selected.sources.length)el('li','No purchased-part source is assigned to this mechanical feature.',list);}
function buttons(){for(const button of document.querySelectorAll('[data-view]'))button.setAttribute('aria-pressed',String(button.dataset.view===view));}
function map(){const host=$('stage'),[x,y,w,h]=board.geometry.bounds,root=svg('svg',{viewBox:`${x-3} ${y-3} ${w+6} ${h+6}`,role:'group','aria-label':`Native PCB connectivity map${net?' highlighting '+net:''}`},host);svg('rect',{x,y,width:w,height:h,rx:'.25',fill:'#f7fafb',stroke:'#6d899b','stroke-width':'.16'},root);
 const color=n=>n==='GND'?'#516f89':n===net?'#b86c08':'#a2603b';for(const track of board.geometry.tracks){const hit=net&&track.net===net;svg('line',{x1:track.start[0],y1:track.start[1],x2:track.end[0],y2:track.end[1],stroke:track.side==='bottom'?'#5684aa':color(track.net),'stroke-width':track.width,'stroke-linecap':'round','stroke-dasharray':track.side==='bottom'?'.8 .5':'none','class':'route'+(net?(hit?' hit':' dim'):'')},root);}
 for(const via of board.geometry.vias){svg('circle',{cx:via.position[0],cy:via.position[1],r:via.width/2,fill:color(via.net),stroke:'#f7fafb','stroke-width':'.12','class':net?(via.net===net?'hit':'dim'):''},root);}
 for(const p of board.geometry.components){for(const pad of p.pads){const[xp,yp]=pad.position,[pw,ph]=pad.size;const marker=svg('ellipse',{cx:xp,cy:yp,rx:pw/2,ry:ph/2,transform:`rotate(${-pad.angle} ${xp} ${yp})`,fill:pad.net?color(pad.net):'#9cacb6',tabindex:'0',role:'button','aria-label':`${p.reference} pad ${pad.number||'hole'} ${pad.net||'no net'}`,'class':'pad'+(net?(pad.net===net?' hit':' dim'):'')},root);svg('title',{},marker).textContent=`${p.reference}.${pad.number||'hole'} ${pad.net||'no net'}`;const activate=()=>{selected=p;parts();chooseNet(pad.net);};marker.addEventListener('click',activate);marker.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}});if(pad.drill[0])svg('ellipse',{cx:xp,cy:yp,rx:pad.drill[0]/2,ry:pad.drill[1]/2,fill:'#f7fafb','pointer-events':'none',transform:`rotate(${-pad.angle} ${xp} ${yp})`},root);}
  if(p===selected&&p.pads.length){const xs=p.pads.flatMap(q=>[q.position[0]-q.size[0]/2,q.position[0]+q.size[0]/2]),ys=p.pads.flatMap(q=>[q.position[1]-q.size[1]/2,q.position[1]+q.size[1]/2]);svg('rect',{x:Math.min(...xs)-.6,y:Math.min(...ys)-.6,width:Math.max(...xs)-Math.min(...xs)+1.2,height:Math.max(...ys)-Math.min(...ys)+1.2,rx:'.3','class':'marker'},root);svg('text',{x:Math.min(...xs)-.4,y:Math.min(...ys)-1},root).textContent=p.reference;}}
}
function stage(){const host=$('stage');host.replaceChildren();if(view==='map')map();else el('img',null,host,{src:board.images[view].uri,alt:`${board.title}: ${titles[view]}`,'class':view==='model'?'model':''});const contacts=net?board.geometry.components.flatMap(p=>p.pads.filter(q=>q.net===net).map(q=>`${p.reference}.${q.number}`)):[];$('caption').textContent=view==='map'?`${net?net+' connects '+contacts.join(', ')+'. ':''}Native pad centers and straight tracks; dashed lines are bottom-layer routes. Filled zones, arcs and exact pad outlines are omitted. Use the native copper views for complete geometry.`:board.images[view].caption;$('live').textContent=`${board.title}. ${titles[view]}.${net?' Selected net '+net+'.':''}`;}
function selectBoard(value){board=data.boards.find(b=>b.id===value);selected=board.geometry.components.find(p=>p.reference==='U1')||board.geometry.components.find(p=>p.reference==='J1')||board.geometry.components[0];net='';$('search').value='';$('title').textContent=board.title;$('subtitle').textContent=board.subtitle;$('result').textContent=`Recorded ERC ${board.erc} / DRC ${board.drc} / unconnected ${board.unconnected}`;for(const b of document.querySelectorAll('[data-board]'))b.setAttribute('aria-pressed',String(b.dataset.board===value));const select=$('net');select.replaceChildren();el('option','Highlight a net',select,{value:''});for(const n of [...new Set(board.geometry.components.flatMap(p=>p.pads.map(q=>q.net).filter(Boolean)))].sort())el('option',n,select,{value:n});$('boundaries').replaceChildren();for(const item of board.boundaries)el('li',item,$('boundaries'));$('pcb-sha').textContent=board.pcb_sha256;$('source-count').textContent=`${Object.keys(board.source_inputs).length} declared source identities. ${board.geometry.components.length} native footprints. KiCad ${board.geometry.kicad_version}.`;$('schematic-pdf').href=board.pdf;$('schematic-pdf').download=board.id+'-schematic.pdf';$('review-link').href=board.review_url;$('source-ledger').replaceChildren();for(const[name,hash]of Object.entries(board.source_inputs)){el('dt',name,$('source-ledger'));el('dd',hash||'Absent input', $('source-ledger'));}buttons();parts();detail();stage();}
for(const b of data.boards){const button=el('button',b.title,$('boards'),{'data-board':b.id,'aria-pressed':'false'});button.addEventListener('click',()=>selectBoard(b.id));}for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>{view=b.dataset.view;buttons();stage();});$('search').addEventListener('input',parts);$('net').addEventListener('change',e=>chooseNet(e.target.value));$('clear').addEventListener('click',()=>chooseNet(''));document.documentElement.classList.add('enhanced');selectBoard(board.id);
'''


def render_explorer(data: dict) -> bytes:
    encoded = json.dumps(data, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
    encoded = encoded.replace('\u2028', '\\u2028').replace('\u2029', '\\u2029')
    script_hash = base64.b64encode(hashlib.sha256(JS.encode()).digest()).decode()
    first = data['boards'][0]
    fallback = ''.join(f'<details><summary>{html.escape(b["title"])}</summary>'
                       f'<p>{html.escape(b["subtitle"])}</p><img alt="Native schematic" '
                       f'src="{b["images"]["schematic"]["uri"]}"></details>' for b in data['boards'])
    source = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'sha256-{script_hash}'; connect-src 'none'; base-uri 'none'; form-action 'none'">
<title>PCB Copilot / Follow a signal</title><style>{CSS}</style></head><body>
<a class="skip" href="#workbench">Skip to the board explorer</a><main class="shell">
<header class="mast"><div><div class="brand">PCB Copilot / Example workbench</div><h1>Follow a signal.</h1>
<p class="lead">Real KiCad boards. Pick a component, trace its saved nets, inspect the native views, and open its manufacturer evidence.</p></div>
<p class="notice">Unbuilt prototypes. Native checks and byte verification have a limited scope. Physical fit, circuit behavior, assembly and human release decisions remain open.</p></header>
<noscript><p>Enable JavaScript for component search and net highlighting. Native schematic pages remain available below.</p>{fallback}</noscript>
<nav id="boards" aria-label="Example board"></nav><section id="workbench" aria-label="Board explorer">
<div class="board-head"><div><h2 id="title">{html.escape(first['title'])}</h2><p id="subtitle">{html.escape(first['subtitle'])}</p></div><span id="result" class="result"></span></div>
<div class="workspace"><aside class="inventory" aria-label="Physical component inventory"><div class="tools"><label for="search">Find a reference, MPN, pin or net</label><input type="search" id="search" placeholder="U1, GND, SDA…"><p id="part-count" class="count"></p></div><div id="parts" class="parts"></div></aside>
<div class="viewer"><div class="viewbar" role="group" aria-label="Board view"><button data-view="model" aria-pressed="true">3D render</button><button data-view="map" aria-pressed="false">Net map</button><button data-view="schematic" aria-pressed="false">Schematic</button><button data-view="top" aria-pressed="false">Top copper</button><button data-view="bottom" aria-pressed="false">Bottom copper</button><select id="net" aria-label="Highlight net"></select><button id="clear">Clear net</button></div><div id="stage" class="stage"></div><div id="caption" class="caption"></div></div>
<aside id="detail" class="detail" aria-label="Selected component and pins"></aside></div>
<div class="bottom"><section class="boundaries"><h3>Check the engineering boundary</h3><ul id="boundaries" class="boundary-list"></ul><a id="schematic-pdf" class="download">Download native vector schematic</a><br><a id="review-link" target="_blank" rel="noopener noreferrer">Read the complete recorded review</a></section>
<section class="ledger"><h3>Bound to saved sources</h3><p id="source-count"></p><p>Native PCB SHA-256<code id="pcb-sha" class="fingerprint"></code></p><details><summary>Inspect the complete input ledger</summary><dl id="source-ledger"></dl></details></section></div></section>
<p class="footer">An offline recorded inspection aid. No design edits, supplier order, approval or hardware communication occurs here. The net map omits pours and exact pad shapes; native copper views remain authoritative for geometry. Local manifest verification checks identities, not authenticity or engineering correctness.</p><p id="live" role="status" aria-live="polite" class="count"></p>
</main><script type="application/json" id="explorer-data">{encoded}</script><script>{JS}</script></body></html>'''
    return source.encode()
